<?php
if (session_status() === PHP_SESSION_NONE) session_start();
if (empty($_SESSION['user_id'])) { header('Location: login.php'); exit; }
$phone = preg_replace('/\D+/', '', (string)($_GET['phone'] ?? ''));
$name = trim((string)($_GET['name'] ?? 'WhatsApp')) ?: 'WhatsApp';
if (strlen($phone) < 10 || strlen($phone) > 15) { http_response_code(422); exit('Telefone inválido.'); }
?><!doctype html>
<html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Conversa WhatsApp - <?= htmlspecialchars($name, ENT_QUOTES, 'UTF-8') ?></title><link rel="stylesheet" href="assets/css/bootstrap.min.css"><link rel="stylesheet" href="assets/css/fontawesome.min.css"><style>
*{box-sizing:border-box}html,body{height:100%;margin:0}body{font-family:Inter,Arial,sans-serif;background:#efeae2;display:flex;flex-direction:column}.chat-head{background:#075e54;color:#fff;padding:14px 16px;display:flex;align-items:center;gap:10px}.chat-head .avatar{width:38px;height:38px;border-radius:50%;background:#d9fdd3;color:#075e54;display:flex;align-items:center;justify-content:center;font-weight:700}.chat-head strong{display:block}.chat-head small{opacity:.8}.chat-body{flex:1;overflow-y:auto;padding:18px 12px;display:flex;flex-direction:column;gap:8px;background-color:#efeae2;background-image:radial-gradient(#d8d0c4 1px,transparent 1px);background-size:18px 18px}.bubble{max-width:86%;padding:9px 11px;border-radius:10px;white-space:pre-wrap;word-break:break-word;box-shadow:0 1px 1px rgba(0,0,0,.12);font-size:14px}.bubble.in{align-self:flex-start;background:#fff}.bubble.out{align-self:flex-end;background:#d9fdd3}.bubble small{display:block;text-align:right;color:#667781;font-size:10px;margin-top:4px}.chat-foot{padding:10px;background:#f0f2f5;border-top:1px solid #d9dde0}.chat-foot form{display:flex;gap:8px}.chat-foot input{border:0;border-radius:20px;padding:10px 14px}.chat-foot button{width:42px;height:42px;border-radius:50%}.empty{margin:auto;color:#667781;background:rgba(255,255,255,.75);padding:10px 14px;border-radius:10px}.status{font-size:11px;margin-left:auto;opacity:.8}
</style></head><body><header class="chat-head"><div class="avatar"><i class="fa-brands fa-whatsapp"></i></div><div><strong id="chatName"><?= htmlspecialchars($name, ENT_QUOTES, 'UTF-8') ?></strong><small><?= htmlspecialchars($phone, ENT_QUOTES, 'UTF-8') ?></small></div><span class="status" id="chatStatus">Conectado</span></header><main id="messages" class="chat-body"><div class="empty">Carregando conversa...</div></main><footer class="chat-foot"><form id="sendForm"><input id="messageInput" class="form-control" maxlength="4096" placeholder="Digite uma mensagem..." autocomplete="off"><button class="btn btn-success" title="Enviar"><i class="fa fa-paper-plane"></i></button></form></footer><script>
const phone=<?= json_encode($phone) ?>, box=document.getElementById('messages'), input=document.getElementById('messageInput'), statusEl=document.getElementById('chatStatus');
function esc(v){const d=document.createElement('div');d.textContent=String(v||'');return d.innerHTML}
async function load(){try{const r=await fetch('api/wa_conversation.php?phone='+encodeURIComponent(phone),{cache:'no-store'}),j=await r.json();const rows=j.messages||[];box.innerHTML=rows.length?rows.map(m=>'<div class="bubble '+(m.direction==='out'?'out':'in')+'">'+esc(m.message_text)+'<small>'+esc(m.sent_at||'')+'</small></div>').join(''):'<div class="empty">Nenhuma mensagem de texto registrada.</div>';box.scrollTop=box.scrollHeight;statusEl.textContent='Atualizado agora'}catch(e){statusEl.textContent='Sem conexão'}}
document.getElementById('sendForm').addEventListener('submit',async e=>{e.preventDefault();const text=input.value.trim();if(!text)return;input.disabled=true;try{const fd=new FormData();fd.append('phone',phone);fd.append('message',text);const r=await fetch('api/wa_conversation.php',{method:'POST',body:fd}),j=await r.json();if(!r.ok||!j.success)throw new Error(j.message||'Falha ao enviar');input.value='';await load()}catch(e){alert(e.message)}finally{input.disabled=false;input.focus()}});load();setInterval(load,4000);
</script></body></html>
